// Shared player for all *_optimized.json scenarios
function CoachScenarioPlayer({ scenario, vehicle, userName }) {
  const [stepId, setStepId] = useState(scenario.entry_step_id || scenario.steps[0].id);
  const [flags, setFlags] = useState({});
  const step = applyVariants(scenario.steps.find(s => s.id === stepId), vehicle);
  const asset = scenario.visual_assets.find(a => a.key === step.visual_asset_key);
  const rules = matchAdaptiveRules(scenario.adaptive_rules, vehicle);

  const body = injectTokens(
    [step.personalize, step.description, ...rules.map(r => r.coach_note)].filter(Boolean).join('\n\n'),
    { ...vehicle, name: userName }
  );

  function onPress(btn) {
    if (btn.set_flags) setFlags(f => ({ ...f, ...btn.set_flags }));
    switch (btn.action) {
      case 'goto':
      case 'skip_to':
        setStepId(btn.next_step_id || btn.payload);
        break;
      case 'next_step': {
        const edge = step.branches?.find(b => b.when_button_id === btn.id);
        setStepId(edge?.goto || linearNext(scenario, stepId));
        break;
      }
      case 'book_shop': return openShopFinder();
      case 'open_chat': return openChat(btn.payload);
      case 'open_parts': return openParts(btn.payload);
      case 'take_photo': return openCamera();
      case 'log_maintenance': return logAndComplete(btn.payload);
      case 'mark_done': return navigation.goBack();
      case 'show_video': return fullscreen(btn.payload);
      default: break;
    }
  }

  // Enforce ux_rules.max_action_buttons === 2
  const buttons = step.action_buttons.slice(0, scenario.ux_rules?.max_action_buttons ?? 2);

  return (
    <SafeAreaView style={shell}>
      {scenario.ux_rules?.show_progress_bar && (
        <ProgressBar
          fraction={step.progress?.fraction ?? 0}
          label={step.progress?.label}
        />
      )}
      <CoachMedia type={step.visual_type} src={asset?.src} poster={asset?.poster} autoPlay loop />
      <Text style={title}>{step.title}</Text>
      {step.coach_encourage && <Text style={encourage}>{step.coach_encourage}</Text>}
      <Text style={bodyText}>{body}</Text>
      {step.trust_nudge && <TrustBanner text={step.trust_nudge} />}
      {step.safety_warning && <SafetyBanner text={step.safety_warning} />}
      <View style={actions}>
        {buttons.map(btn => (
          <CoachButton key={btn.id} {...btn} onPress={() => onPress(btn)} />
        ))}
      </View>
      <VoiceCoachChip onPress={startLiveRepairMode} />
    </SafeAreaView>
  );
}
